package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

// ここにパッケージ変数 balance と関数 apply(n int) を定義する

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	fields := strings.Fields(sc.Text())
	nums := make([]int, len(fields))
	for i, f := range fields {
		nums[i], _ = strconv.Atoi(f)
	}
	// ここから下を書く（nums を順に apply して balance を出力する）
	_ = nums
	_ = fmt.Println
}

